import{z as l,x as o,o as B,c as p,q as t,j as A,D as e,d as E,s as i,S as n,b as s}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"稀疏计算","description":"","frontmatter":{"title":"稀疏计算","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sc-sparse-computing.md","filePath":"cs/sc-sparse-computing.md","lastUpdated":1791413859000}'),C={name:"cs/sc-sparse-computing.md"};function d(c,a,m,F,D,S){const r=o("Mermaid");return B(),p("div",null,[a[2]||(a[2]=t('<h1 id="稀疏计算" tabindex="-1">稀疏计算 <a class="header-anchor" href="#稀疏计算" aria-label="Permalink to &quot;稀疏计算&quot;">​</a></h1><div class="epigraph"><p>稀疏计算省下的是零的存储与乘法，付出的是间接寻址与填入；账算不算得平，取决于零是怎么分布的。</p><footer>—— 据 Davis, Direct Methods for Sparse Linear Systems, SIAM, 2006；Duff, Erisman and Reid, Direct Methods for Sparse Matrices, 1986 整理</footer></div><p><a href="/cs/sc-blas-levels">上一课</a>的红利——每 flop 搬 \\(O(1/n)\\) 字节——依赖稠密的规则性；图、网格离散与推荐矩阵把九成九的元素交成零，规则性随之消失。本课把线性代数搬进稀疏世界。主干已给过<a href="/cs/csr-graph">边表与 CSR</a> 的存储视角；缺口是：稀疏格式怎么服务线性代数、SpMV 为什么停在带宽上、直接分解的成本为什么被填入而不是浮点决定。后课默认你按非零数与填入记账。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n=10^7\\) 的三维网格矩阵，稠密存放要 \\(8\\times10^{14}\\) 字节，物理上不可行；它的非零只有约 \\(7n\\) 个，稀疏存放几十字节级就能装下。存下来了，新的问题才开始：每行非零个数不一，间接寻址取代连续访存，level-3 的分块复用难产；做直接分解，浮点不是主要成本，消元把零变成非零的<strong>填入</strong>才是。缺口是三笔账：存储账（格式跟访问模式走）、带宽账（SpMV 的天花板）、填入账（分解的真实成本）。三笔账不分，就会在错误的层面优化。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三种基本格式分工。COO 三元组管构造：插入任意次序的行列值，装配阶段用完即弃。CSR 行压缩管 SpMV 与行操作：行指针加列索引加值，一次遍历每个非零恰好做一次乘加。CSC 管列访问与分解：消元按列写回时用它。格式没有优劣，只有与访问模式的匹配——用 COO 做迭代求解的内层，或在 CSR 上频繁插列，都是在错的格式上付钱。<span class="marginnote">数字实例：一个 \\(10^6\\times10^6\\)、每行 5 个非零的矩阵，稠密存放要 \\(8\\times10^{12}\\) 字节（8 TB）；CSR 存 \\(5\\times10^6\\) 个值加同量级索引与行指针，约 80 MB——差五个数量级。但每个 flop 的搬运没有变便宜：一个非零连带 4 字节索引加一次间接读，这正是 SpMV 停在带宽上的原因。</span></p><p>SpMV 的账最好算：时间正比非零数，但每个非零要连带一个 4 字节列索引，8 字节值加 4 字节索引加一次间接读 \\(x_j\\)，每 flop 的搬运量反而回到 level-1 的量级——纯带宽问题，预取与重排只在常数上打转。直接法的账难算得多：稀疏 Cholesky 与 LU 的成本在填入，消元图上每步消去一个顶点、把它的邻居两两连边，填入就是补出来的边；排序算法（最小度、嵌套剖分）全部在图上做文章，<a href="/cs/csr-graph">边表与 CSR</a> 的图表示在这里直接接上。</p><p><span class="marginnote">交叉点常被忽略：非零密度上去或 \\(n\\) 不大时，稠密反而赢——CSR 每个非零背约 12 字节的存储税与一次间接寻址，\\(n=2000\\)、密度两成的矩阵，稠密 gemm 的分块复用早已把稀疏的开销甩开。选稀疏前先问非零比例与维数，不是先问库。</span></p>',9)),(B(),A(n,null,{default:e(()=>[i(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20FMT%5B%22%E6%A0%BC%E5%BC%8F%EF%BC%9ACOO%20%2F%20CSR%20%2F%20CSC%22%5D%20--%3E%20MV%5B%22SpMV%EF%BC%9A%E6%97%B6%E9%97%B4%E6%AF%94%E9%9D%9E%E9%9B%B6%E6%95%B0%EF%BC%8C%E5%B8%A6%E5%AE%BD%E9%92%89%E6%AD%BB%22%5D%0A%20%20FMT%20--%3E%20FACT%5B%22%E7%9B%B4%E6%8E%A5%E6%B3%95%EF%BC%9ALU%20%E4%B8%8E%20Cholesky%22%5D%0A%20%20FACT%20--%3E%20FILL%5B%22%E5%A1%AB%E5%85%A5%EF%BC%9A%E6%B6%88%E5%85%83%E5%9B%BE%E4%B8%8A%E8%A1%A5%E8%BE%B9%22%5D%0A%20%20FILL%20--%3E%20ORD%5B%22%E6%8E%92%E5%BA%8F%EF%BC%9A%E6%9C%80%E5%B0%8F%E5%BA%A6%E4%B8%8E%E5%B5%8C%E5%A5%97%E5%89%96%E5%88%86%22%5D%0A%20%20ORD%20--%3E%20NUM%5B%22%E6%95%B0%E5%80%BC%EF%BC%9A%E8%B7%AF%E5%BE%84%E6%94%B9%E5%8F%98%EF%BC%8C%E4%B8%BB%E5%85%83%E5%90%88%E5%90%8C%E4%BB%8D%E5%9C%A8%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[E("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,[E("填入为什么是图论问题：对称正定矩阵的消元一一对应图的顶点消去，填入量由消去顺序决定而与数值无关——二维网格上嵌套剖分把填入从 \\(O(n^2)\\) 压到 \\(O(n\\log n)\\) 量级，三维网格上填入涨得太快，直接法本身开始不合算，接力棒交给"),s("a",{href:"/cs/iterative-solver-converge"},"迭代法何时收敛"),E("。这是「分解还是迭代」的真实分界：不是品味，是维数与填入的账。")],-1)),(B(),A(n,null,{default:e(()=>[i(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20STAR%5B%22%E6%98%9F%E5%BD%A2%E6%B6%88%E5%85%83%E5%9B%BE%EF%BC%9A%E4%B8%AD%E5%BF%83%200%20%E8%BF%9E%E5%8F%B6%E5%AD%90%201%2C2%2C3%2C4%22%5D%20--%3E%20C0%5B%22%E5%85%88%E6%B6%88%E4%B8%AD%E5%BF%83%200%22%5D%0A%20%20C0%20--%3E%20FILL%5B%22%E5%9B%9B%E4%B8%AA%E5%8F%B6%E5%AD%90%E4%B8%A4%E4%B8%A4%E8%BF%9E%E8%BE%B9%3Cbr%2F%3E%E4%B8%80%E6%AC%A1%E8%A1%A5%206%20%E6%9D%A1%E5%A1%AB%E5%85%A5%22%5D%0A%20%20STAR%20--%3E%20L1%5B%22%E5%85%88%E6%B6%88%E5%8F%B6%E5%AD%90%201%22%5D%0A%20%20L1%20--%3E%20NOFILL%5B%22%E4%B8%AD%E5%BF%83%E8%BF%98%E5%9C%A8%EF%BC%8C%E6%97%A0%E8%A1%A5%E8%BE%B9%22%5D%0A%20%20NOFILL%20--%3E%20L2%5B%22%E5%86%8D%E6%B6%88%202%2C3%2C4%EF%BC%9A%E5%90%8C%E6%A0%B7%E9%9B%B6%E5%A1%AB%E5%85%A5%22%5D%0A%20%20FILL%20--%3E%20ORD%5B%22%E5%90%8C%E4%B8%80%E7%9F%A9%E9%98%B5%E3%80%81%E9%A1%BA%E5%BA%8F%E4%B8%8D%E5%90%8C%3Cbr%2F%3E%E5%A1%AB%E5%85%A5%E5%B7%AE%E5%87%BA%E4%B8%80%E4%B8%AA%E6%95%B0%E9%87%8F%E7%BA%A7%22%5D%0A%20%20L2%20--%3E%20ORD%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">嵌套剖分可以想象成「先分块再拼装」：把网格递归对半切开，先消各块内部的变量，最后才处理切缝上的少数接缝变量——接缝少，补的边就少。二维网格上这一招把填入从 \\(O(n^2)\\) 量级压到接近 \\(O(n\\log n)\\)；三维上接缝本身就有 \\(n^{2/3}\\) 量级，压不动，直接法开始让位给迭代法。</span></p><p>数值上，重排与消元顺序不改精确解，改浮点路径：为少填入选的行序与为稳定选的行序会打架，<a href="/cs/gaussian-pivoting">高斯消元与主元</a>的部分主元合同在稀疏里多一条约束，超节点方法把两者折中。带着稠密直觉进场的人两头翻车：在 SpMV 上追峰值（它是带宽问题），或忽略填入直接分解（三维问题上内存先爆）。<span class="marginnote">初学者容易以为「换个稀疏格式」能救活太慢的直接法，实际上格式只影响存储与 SpMV 的访存方式，直接法的成本大头在填入与排序——不换排序策略，等于账本一个字没改。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不进迭代法内部、不进并行稀疏三角求解与调度，低秩近似与压缩感知是统计与信号的对象，不在此。数据结构课的稀疏集合管成员判定，与这里的线性代数稀疏是两回事。后课默认：稀疏按非零数与填入记账，SpMV 是带宽问题，直接分解先问填入再问浮点。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>COO 管构造、CSR 管行、CSC 管列；格式跟着访问模式走。</li><li>SpMV 时间正比非零数、受带宽钉死；level-3 红利在稀疏里难产。</li><li>直接法的成本在填入：填入是消元图补边，排序算法在图上做文章。</li><li>重排不改精确解、改浮点路径；填入与主元稳定要折中。</li><li>出处：Davis, SIAM, 2006；Duff, Erisman and Reid, 1986；Saad, Iterative Methods for Sparse Linear Systems。</li></ul>',6))])}const u=l(C,[["render",d]]);export{f as __pageData,u as default};
